import { responseJSON } from '@xsai/shared';
import { chat, determineStepType, executeTool } from '@xsai/shared-chat';

const rawGenerateText = async (options) => chat({
  ...options,
  maxSteps: void 0,
  messages: options.messages,
  steps: void 0,
  stream: false
}).then(responseJSON).then(async (res) => {
  const { choices, usage } = res;
  if (!choices?.length)
    throw new Error(`No choices returned, response body: ${JSON.stringify(res)}`);
  const messages = structuredClone(options.messages);
  const steps = options.steps ? structuredClone(options.steps) : [];
  const toolCalls = [];
  const toolResults = [];
  const { finish_reason: finishReason, message } = choices[0];
  const msgToolCalls = message?.tool_calls ?? [];
  const stepType = determineStepType({
    finishReason,
    maxSteps: options.maxSteps ?? 1,
    stepsLength: steps.length,
    toolCallsLength: msgToolCalls.length
  });
  messages.push({ ...message, content: message.content });
  if (finishReason === "stop" || stepType === "done") {
    const step2 = {
      finishReason,
      stepType,
      text: message.content,
      toolCalls,
      toolResults,
      usage
    };
    steps.push(step2);
    if (options.onStepFinish)
      await options.onStepFinish(step2);
    return {
      finishReason,
      messages,
      steps,
      text: message.content,
      toolCalls,
      toolResults,
      usage
    };
  }
  for (const toolCall of msgToolCalls) {
    const { parsedArgs, result, toolName } = await executeTool({
      abortSignal: options.abortSignal,
      messages,
      toolCall,
      tools: options.tools
    });
    const toolInfo = { toolCallId: toolCall.id, toolName };
    toolCalls.push({ ...toolInfo, args: toolCall.function.arguments, toolCallType: toolCall.type });
    toolResults.push({ ...toolInfo, args: parsedArgs, result });
    messages.push({
      content: result,
      role: "tool",
      tool_call_id: toolCall.id
    });
  }
  const step = {
    finishReason,
    stepType,
    text: message.content,
    toolCalls,
    toolResults,
    usage
  };
  steps.push(step);
  if (options.onStepFinish)
    await options.onStepFinish(step);
  return async () => rawGenerateText({
    ...options,
    messages,
    steps
  });
});
const generateText = async (options) => {
  let result = await rawGenerateText(options);
  while (typeof result === "function")
    result = await result();
  return result;
};

export { generateText };
